  safe:        { flex: 1, backgroundColor: '#050507' },
  header:      { flexDirection: 'row', alignItems: 'center', paddingHorizontal: 12, paddingVertical: 10, borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: '#1A1A24' },
  backBtn:     { width: 44, height: 44, alignItems: 'center', justifyContent: 'center', borderRadius: Radius.md, marginRight: 8, backgroundColor: '#0C0C14', borderWidth: 1, borderColor: '#181820' },
